mapper.select:
select 


order by esr.evaluation_year desc, ea.area_code, ei.item_code, ee.element_code, emi.management_item_code, esr.organization_code, esr.effective_start_date desc
limit #{criteria.safeSize} offset #{criteria.offset}

select version_status
from evaluation_rule_versions
where rule_version_id = #{ruleVersionId}

select exists(
    select 1
    from evaluation_management_items emi
    inner join evaluation_elements ee on ee.element_id = emi.element_id
    inner join evaluation_items ei on ei.item_id = ee.item_id
    inner join evaluation_areas ea on ea.area_id = ei.area_id
    where emi.management_item_id = #{managementItemId}
      and ea.rule_version_id = #{ruleVersionId}
)

select 

where esr.rule_version_id = #{request.ruleVersionId}
  and esr.management_item_id = #{request.managementItemId}
  and esr.organization_code = #{request.organizationCode}
  and esr.evaluation_year = #{request.evaluationYear}
  and esr.effective_start_date = #{request.effectiveStartDate}
  and esr.effective_end_date = #{request.effectiveEndDate}
